from pathlib import Path
import subprocess,json
r=Path(__file__).resolve().parents[1]
roots = ['either::Either::is_left', 'either::Either::is_right', 'either::Either::left', 'either::Either::right', 'either::Either::flip', 'either::Either::left_or', 'either::Either::right_or', 'either::Either::left_and', 'either::Either::right_and', 'either::Either::factor_none', 'either::Either::factor_first', 'either::Either::factor_second', 'either::Either::as_ref', 'either::Either::as_mut', 'either::Either::is_left_and', 'either::Either::is_right_and', 'either::Either::is_left_or', 'either::Either::is_right_or', 'either::Either::map_left', 'either::Either::map_right', 'either::Either::map_left_or', 'either::Either::map_right_or', 'either::Either::left_or_else', 'either::Either::right_or_else', 'either::Either::left_and_then', 'either::Either::right_and_then', 'either::into_either::IntoEither::into_either', 'either::into_either::IntoEither::into_either_with', '{impl either::into_either::IntoEither for _}', '{impl core::convert::From for either::Either}::from', '{impl core::convert::From for core::result::Result}::from', 'either::Either::left_or_default', 'either::Either::right_or_default', 'either::Either::either', 'either::Either::either_with', 'either::Either::either_into', 'either::Either::map_either', 'either::Either::map_either_with', 'either::Either::inspect_left', 'either::Either::inspect_right', '{impl core::iter::traits::iterator::Iterator for either::Either}::next']
roots += ['{impl core::iter::traits::double_ended::DoubleEndedIterator for either::Either}::next_back']
